class Solution:
    def findPeaks(self, mountain: List[int]) -> List[int]:
        return [i for i in range(1, len(mountain)-1) if mountain[i] > mountain[i-1] and mountain[i] > mountain[i+1]]

add-to-array-form-of-integer:
class Solution:
    def addToArrayForm(self, num: List[int], k: int) -> List[int]:
        num = [str(x) for x in num]
        n = int(''.join(num)) + k
        return [int(d) for d in str(n)]

apple-redistribution-into-boxes:
class Solution:
    def minimumBoxes(self, apple: List[int], capacity: List[int]) -> int:
        total = sum(apple)
        capacity.sort(reverse=True)
        for i, c in enumerate(capacity):
            total -= c
            if total <= 0:
                return i + 1
        return len(capacity)

binary-tree-tilt:
class Solution:
    def findTilt(self, root: Optional[TreeNode]) -> int:
        self.total = 0
        def go(node):
            if not node:
                return 0
            l = go(node.left)
            r = go(node.right)
            self.total += abs(l - r)
            return l + r + node.val
        go(root)
        return self.total

button-with-longest-push-time:
class Solution:
    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        best_i = events[0][0]
        best_t = events[0][1]
        for j in range(1, len(events)):
            t = events[j][1] - events[j - 1][1]
            if t > best_t:
                best_t = t
                best_i = events[j][0]
        return best_i

calculate-digit-sum-of-a-string:
class Solution:
    def digitSum(self, s: str, k: int) -> int:
        while len(s) > k:
            s = ''.join(str(sum(int(c) for c in s[i:i + k])) for i in range(0, len(s), k))
        return int(s)
